/*<info serverAlias="DBCRM-bodb_CRM" executers="bodbAdminNet" viewers="" isFunction="0"></info>*/ALTER PROCEDURE [dbo].[Acc_CRM_CurrencyList_Redemption]AS/*	Created: Dom	Date: 20141117	Task : Get list currency for redemption	DB: DBCRM.bodb_CRM	Original:	Revisions:			Param's Explanation:			*/begin	select ExchangeID CurrencyID, Currency from bodb02.dbo.exchange WITH(NOLOCK) where ExchangeID IN(3,6,5,33,2,13,43,45)end